import React, { FC, useEffect, useState } from "react";
import axios from "axios";
import { useCookies } from "react-cookie";
import { Form, Formik } from "formik";
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer,
  BarChart, Bar, Legend, PieChart, Pie, Cell
} from 'recharts';

import useTheme from "../../context/Theme/useTheme";
import { keys } from "../../context/Theme/Palettes";
import Select from "../../Components/Select";
import CartTable from "../../Components/CartTable";
import UserRow from "./UserRow";
import TextField from "../../Components/TextField";
import Button from "../../Components/Button";
import { userSchema } from "../../schema";
import useSnackbar from "../../context/Snackbar/useSnackbar";
import style from "./style.module.css";
import InventoryForecastWidget from "./InventoryForecastWidget";
import EmployeeAnalyticsWidget from "./EmployeeAnalyticsWidget";

import ExpiryAlertsWidget from "./ExpiryAlertsWidget";

import AIMAssistantWidget from "./AIMAssistantWidget";

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d'];

const Dashboard: FC = () => {
  const snack = useSnackbar();
  const theme = useTheme();
  const [cookies] = useCookies();
  const isAdmin = cookies.auth.admin;

  const [carts, setCarts] = useState<Cart[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Analytics State
  const [todayStats, setTodayStats] = useState<any>({ revenue: 0, orders: 0, averageSale: 0 });
  const [weekStats, setWeekStats] = useState<any>({ chartData: [], summary: { revenue: 0, orders: 0 } });
  const [monthStats, setMonthStats] = useState<any>({ chartData: [], summary: { revenue: 0, orders: 0 } });
  const [productStats, setProductStats] = useState<any[]>([]);
  const [stockStats, setStockStats] = useState<any>({ totalProducts: 0, lowStockCount: 0 });
  const [netProfitStats, setNetProfitStats] = useState<any>({ revenue: 0, costOfGoods: 0, grossProfit: 0, expenses: 0, netProfit: 0 });
  const [valuationStats, setValuationStats] = useState<any>({ totalCostValue: 0, totalRetailValue: 0, potentialProfit: 0 });
  const [auditLogs, setAuditLogs] = useState<any[]>([]);

  const [revenueView, setRevenueView] = useState<"week" | "month">("week");

  useEffect(() => {
    axios.defaults.headers.common.Authorization = "barear " + cookies.auth.token;

    // Fetch existing dashboard data
    axios.get("/cart/carts").then((res) => {
      let cartsList = res.data.map((c: any) => ({
        cartId: c._id,
        description: c.description,
        tax: c.tax,
        discount: c.discount,
        products: c.products.map((p: any) => ({ ...p, qty: p.qty })),
      }));
      setCarts(cartsList);
    });

    if (isAdmin) {
      axios.get("/user/users").then((res) => setUsers(res.data));
      axios.get("/audit").then((res) => setAuditLogs(res.data));

      // Fetch Analytics Data
      Promise.all([
        axios.get("/analytics/today"),
        axios.get("/analytics/week"),
        axios.get("/analytics/month"),
        axios.get("/analytics/products"),
        axios.get("/analytics/low-stock"),
        axios.get("/analytics/net-profit?period=monthly"),
        axios.get("/analytics/valuation"),
      ]).then(([resToday, resWeek, resMonth, resProd, resStock, resNet, resValuation]) => {
        setTodayStats(resToday.data);
        setWeekStats(resWeek.data);
        setMonthStats(resMonth.data);
        setProductStats(resProd.data);
        setStockStats(resStock.data);
        setNetProfitStats(resNet.data);
        setValuationStats(resValuation.data);
      }).catch(err => {
        console.error("Error fetching analytics", err);
      });
    }
  }, [cookies.auth.token, isAdmin]);

  return (
    <div className={style.dashboard}>
      <header className={style.header}>
        <h2>{isAdmin ? "Admin Overview" : "Cashier Dashboard"}</h2>
        <p className={style.subtitle}>Welcome back, here is what's happening today.</p>
      </header>

      {/* 1. ANALYTICS SECTION (Admin Only) */}
      {isAdmin && (
        <div className={style.adminSection}>
          <AIMAssistantWidget />
          
          <h2 style={{ marginBottom: "20px" }}>Dashboard Overview</h2>
          
          {/* Summary Cards */}
          <div className={style.cardsGrid}>
            <div className={style.statCard} style={{ borderColor: theme.palette.secondary }}>
              <h3>Today's Sales</h3>
              <p className={style.statValue}>Ksh {todayStats.revenue.toFixed(2)}</p>
              <span className={style.statSub}>{todayStats.orders} Orders (Avg: Ksh {todayStats.averageSale?.toFixed(2) || "0.00"})</span>
            </div>
            <div className={style.statCard} style={{ borderColor: theme.palette.secondary }}>
              <h3>Today's Profit</h3>
              <p className={style.statValue}>Ksh {(todayStats.profit || 0).toFixed(2)}</p>
              <span className={style.statSub}>Margin: {todayStats.revenue ? ((todayStats.profit / todayStats.revenue) * 100).toFixed(1) : "0"}%</span>
            </div>
            <div className={style.statCard} style={{ borderColor: theme.palette.secondary }}>
              <h3>Weekly Sales</h3>
              <p className={style.statValue}>Ksh {weekStats.summary.revenue.toFixed(2)}</p>
              <span className={style.statSub}>Profit: Ksh {(weekStats.summary.summary?.profit || weekStats.summary.profit || 0).toFixed(2)}</span>
            </div>
            <div className={style.statCard} style={{ borderColor: theme.palette.secondary }}>
              <h3>Monthly Sales</h3>
              <p className={style.statValue}>Ksh {monthStats.summary.revenue.toFixed(2)}</p>
              <span className={style.statSub}>Profit: Ksh {(monthStats.summary.profit || 0).toFixed(2)}</span>
            </div>
            
            <div className={style.statCard} style={{ borderColor: theme.palette.secondary, backgroundColor: "var(--color-primary)", color: "white" }}>
              <h3>Inventory Valuation</h3>
              <p className={style.statValue} style={{ color: "white" }}>Ksh {valuationStats.totalCostValue.toFixed(2)}</p>
              <span className={style.statSub} style={{ color: "white", opacity: 0.9 }}>Retail Val: Ksh {valuationStats.totalRetailValue.toFixed(2)} | Pot. Profit: Ksh {valuationStats.potentialProfit.toFixed(2)}</span>
            </div>
            
            <div className={style.statCard} style={{ borderColor: theme.palette.secondary }}>
              <h3>Total Products</h3>
              <p className={style.statValue}>{stockStats.totalProducts}</p>
            </div>
            <div className={`${style.statCard} ${stockStats.lowStockCount > 0 ? style.dangerCard : ""}`} style={{ borderColor: theme.palette.secondary }}>
              <h3>Low Stock Items</h3>
              <p className={style.statValue}>{stockStats.lowStockCount}</p>
            </div>
            <div className={style.statCard} style={{ borderColor: theme.palette.secondary, backgroundColor: "var(--color-success)", color: "white" }}>
              <h3>Net Profit (Month)</h3>
              <p className={style.statValue} style={{ color: "white" }}>Ksh {netProfitStats.netProfit.toFixed(2)}</p>
              <span className={style.statSub} style={{ color: "white", opacity: 0.9 }}>Gross: Ksh {netProfitStats.grossProfit.toFixed(2)} | Exp: Ksh {netProfitStats.expenses.toFixed(2)}</span>
            </div>
          </div>

          {/* Charts Section */}
          <div className={style.chartsGrid}>
            <div className={style.chartContainer} style={{ backgroundColor: theme.palette.secondary + "11" }}>
              <div className={style.chartHeader}>
                <h3>Revenue Trends</h3>
                <select 
                  value={revenueView} 
                  onChange={(e) => setRevenueView(e.target.value as "week"|"month")}
                  className={style.chartSelect}
                >
                  <option value="week">Last 7 Days</option>
                  <option value="month">Last 30 Days</option>
                </select>
              </div>
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={revenueView === "week" ? weekStats.chartData : monthStats.chartData} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                  <Line type="monotone" dataKey="revenue" stroke={theme.palette.primary} strokeWidth={3} />
                  <CartesianGrid stroke="#ccc" strokeDasharray="5 5" />
                  <XAxis dataKey="date" />
                  <YAxis />
                  <RechartsTooltip />
                </LineChart>
              </ResponsiveContainer>
            </div>

            <div className={style.chartContainer} style={{ backgroundColor: theme.palette.secondary + "11" }}>
              <h3>Top Selling Products (Qty)</h3>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={productStats} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="_id" tickFormatter={(tick) => tick.substring(0, 10)} />
                  <YAxis />
                  <RechartsTooltip />
                  <Legend />
                  <Bar dataKey="qtySold" fill={theme.palette.error} name="Quantity Sold" />
                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className={style.chartContainer} style={{ backgroundColor: theme.palette.secondary + "11" }}>
              <h3>Product Sales Distribution</h3>
              <ResponsiveContainer width="100%" height={300}>
                <PieChart>
                  <Pie
                    data={productStats}
                    cx="50%"
                    cy="50%"
                    outerRadius={100}
                    fill="#8884d8"
                    dataKey="qtySold"
                    nameKey="_id"
                    label={({ name, percent }) => `${(name || "").substring(0, 10)} ${((percent || 0) * 100).toFixed(0)}%`}
                  >
                    {productStats.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <RechartsTooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
          
          <InventoryForecastWidget />
          <EmployeeAnalyticsWidget />
          <ExpiryAlertsWidget />
          
        </div>
      )}

      {isAdmin && <div className={style.divider} style={{ backgroundColor: theme.palette.secondary }} />}

      {/* 2. SETTINGS & SYSTEM CONFIGURATION */}
      <div className={style.mode}>
        <h3>System Theme</h3>
        <Select
          onChange={(value) => theme.changePalette(value.target.value as keys)}
          options={[
            { key: "dark", value: "dark" },
            { key: "primary", value: "white" },
            { key: "green", value: "green" },
            { key: "matrial", value: "matrial" },
          ]}
        />
      </div>

      <div className={style.divider} style={{ backgroundColor: theme.palette.secondary }} />

      {/* 3. CHECKED CARTS */}
      <div className={style.checkedCarts}>
        <h3>ACTIVE CHECKED CARTS</h3>
        <CartTable className={style.list} onChoose={() => {}} noButton carts={carts} />
      </div>

      <div className={style.divider} style={{ backgroundColor: theme.palette.secondary }} />

      {/* 4. USER MANAGEMENT (Admin Only) */}
      {isAdmin && (
        <div className={style.users}>
          <h3>SYSTEM USERS</h3>
          <div className={style.userList}>
            {users.map((u) => (
              <UserRow
                key={u.username}
                onClick={(e) => {
                  axios.delete("/user/delete/" + u.username).then((res) => {
                    snack.onResponse({ message: res.data.message, status: res.status });
                    setUsers(users.filter((user) => user.username !== u.username));
                  });
                }}
                isAdmin={u.admin}
                username={u.username}
              />
            ))}
          </div>
          <div className={style.userCreation}>
            <h4>CREATE NEW USER</h4>
            <Formik
              initialValues={{ username: "", password: "", isAdmin: false }}
              validationSchema={userSchema}
              onSubmit={(values, { resetForm }) => {
                axios.post("/user/create", {
                    username: values.username,
                    password: values.password,
                    admin: values.isAdmin,
                  }).then((res) => {
                    snack.onResponse({ message: res.data.username + " has been created", status: res.status });
                    setUsers((p) => [...p, res.data]);
                    resetForm();
                  }).catch(err => {
                    snack.onResponse({ message: err.response?.data?.message || "Error creating user", status: err.response?.status || 500 });
                  });
              }}
            >
              <Form className={style.form}>
                <p>UserName</p>
                <TextField placeholder="Enter Username" name="username" width="100%" />
                <p>Password</p>
                <TextField placeholder="Enter Password" name="password" type="password" width="100%" />
                <div className={style.row}>
                  <p>Admin?</p>
                  <TextField name="isAdmin" type="checkbox" width="4em" />
                </div>
                <div>
                  <Button type="submit" variant="error">Create User</Button>
                </div>
              </Form>
            </Formik>
          </div>
        </div>
      )}

      {isAdmin && <div className={style.divider} style={{ backgroundColor: theme.palette.secondary }} />}

      {/* 5. SYSTEM AUDIT LOGS (Admin Only) */}
      {isAdmin && (
        <div className={style.users}>
          <h3>SYSTEM AUDIT LOGS</h3>
          <div style={{ maxHeight: "400px", overflowY: "auto", border: `1px solid ${theme.palette.secondary}`, borderRadius: "4px" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "12px" }}>
              <thead style={{ backgroundColor: theme.palette.secondary, color: "white" }}>
                <tr>
                  <th style={{ padding: "8px", textAlign: "left" }}>Time</th>
                  <th style={{ padding: "8px", textAlign: "left" }}>User</th>
                  <th style={{ padding: "8px", textAlign: "left" }}>Action</th>
                  <th style={{ padding: "8px", textAlign: "left" }}>IP Address</th>
                </tr>
              </thead>
              <tbody>
                {auditLogs.map((log: any, idx: number) => (
                  <tr key={idx} style={{ borderBottom: "1px solid #ccc", backgroundColor: idx % 2 === 0 ? "transparent" : theme.palette.secondary + "11" }}>
                    <td style={{ padding: "8px" }}>{new Date(log.timestamp).toLocaleString()}</td>
                    <td style={{ padding: "8px" }}>{log.username}</td>
                    <td style={{ padding: "8px" }}>{log.method} {log.url}</td>
                    <td style={{ padding: "8px" }}>{log.ip}</td>
                  </tr>
                ))}
                {auditLogs.length === 0 && (
                  <tr>
                    <td colSpan={4} style={{ padding: "15px", textAlign: "center" }}>No logs available</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;
